def policy(env, agent_id) -> int:
    """Dynamically split agents into Gatherers and Cleaners to maximize global reward."""

    # Do nothing if the agent is timed out
    if int(env.agent_timeout[agent_id]) > 0:
        return 7

    # 1. DYNAMIC ROLE ASSIGNMENT
    cols = []
    for i in range(env.n_agents):
        if int(env.agent_timeout[i]) > 0:
            cols.append(9999)  # Exclude timed-out agents
        else:
            cols.append(int(env.agent_pos[i][1]))

    # Sort by column to find the leftmost agents
    agent_cols = [(cols[i], i) for i in range(env.n_agents) if cols[i] != 9999]
    agent_cols.sort()

    # Scale number of cleaners (K) based on urgency of total waste
    total_waste = int(np.sum(env.waste))
    if total_waste < 15: K = 2
    elif total_waste < 30: K = 3
    elif total_waste < 50: K = 4
    else: K = 5

    K = min(K, len(agent_cols))
    cleaners = [x[1] for x in agent_cols[:K]]

    # Sort cleaners vertically so they can split up targeting top/middle/bottom river
    cleaners_by_row = sorted(cleaners, key=lambda id: (int(env.agent_pos[id][0]), id))
    is_cleaner = (agent_id in cleaners)

    if is_cleaner:
        c_idx = cleaners_by_row.index(agent_id)
        r = int(env.agent_pos[agent_id][0])
        c = int(env.agent_pos[agent_id][1])

        # Check all 4 orientations to see if we can hit waste with the beam right now
        best_hits = 0
        best_orient = None
        for o in range(4):
            hits = 0
            for d in range(1, 6):
                # Map beam projection
                if o == 0: cells_to_check = [(r-d, c-1), (r-d, c), (r-d, c+1)]     # North
                elif o == 1: cells_to_check = [(r-1, c+d), (r, c+d), (r+1, c+d)]   # East
                elif o == 2: cells_to_check = [(r+d, c-1), (r+d, c), (r+d, c+1)]   # South
                elif o == 3: cells_to_check = [(r-1, c-d), (r, c-d), (r+1, c-d)]   # West

                for cr, cc in cells_to_check:
                    if 0 <= cr < env.height and 0 <= cc < env.width:
                        if env.waste[cr, cc]:
                            hits += 1

            if hits > best_hits:
                best_hits = hits
                best_orient = o

        # If waste is in sight, face it and fire CLEAN (-1 cost is worth it)
        if best_hits >= 1:
            if int(env.agent_orient[agent_id]) == best_orient:
                return 8  # CLEAN
            else:
                diff = (best_orient - int(env.agent_orient[agent_id])) % 4
                if diff == 1: return 5     # ROTATE_RIGHT
                elif diff == 3: return 4   # ROTATE_LEFT
                else: return 5             # 180 turnaround (start rotating right)

        # Group and index current waste
        waste_cells = []
        for wr in range(env.height):
            for wc in range(env.width):
                if env.waste[wr, wc]:
                    waste_cells.append((wr, wc))

        if len(waste_cells) > 0:
            # Divide target waste cells among the active cleaners based on their row rank
            start = len(waste_cells) * c_idx // len(cleaners)
            end = len(waste_cells) * (c_idx + 1) // len(cleaners)
            target_waste = waste_cells[start:end]
            if not target_waste:
                target_waste = waste_cells  # Slice fallback if too small

            result = bfs_to_target_set(env, agent_id, set(target_waste))
            if result is not None:
                dr, dc = result
                return direction_to_action(dr, dc, int(env.agent_orient[agent_id]))

            # Fallback pathing
            result_all = bfs_to_target_set(env, agent_id, set(waste_cells))
            if result_all is not None:
                dr, dc = result_all
                return direction_to_action(dr, dc, int(env.agent_orient[agent_id]))

            # Standing ON waste prevents cleaning it; Step East to clear distance
            if env.waste[r, c]:
                return direction_to_action(0, 1, int(env.agent_orient[agent_id]))

            return 7  # STAND
        else:
            # Patrol designated sector of the river if completely empty
            river_list = sorted(list(env.river_cells_set))
            if len(river_list) > 0:
                start = len(river_list) * c_idx // len(cleaners)
                end = len(river_list) * (c_idx + 1) // len(cleaners)
                target_river = river_list[start:end]
                if not target_river:
                    target_river = river_list

                result = bfs_to_target_set(env, agent_id, set(target_river))
                if result is not None:
                    dr, dc = result
                    return direction_to_action(dr, dc, int(env.agent_orient[agent_id]))

            return 7

    else:
        # 2. GATHERER LOGIC
        result = bfs_nearest_apple(env, agent_id)
        if result is not None:
            dr, dc = result
            return direction_to_action(dr, dc, int(env.agent_orient[agent_id]))

        # If no apples exist, pre-position waiting by the orchard area (~ rightmost 40%)
        orchard_cells = set()
        start_col = int(env.width * 0.6)
        for r in range(env.height):
            for c in range(start_col, env.width):
                if not env.walls[r, c]:
                    orchard_cells.add((r, c))

        result = bfs_to_target_set(env, agent_id, orchard_cells)
        if result is not None:
            dr, dc = result
            return direction_to_action(dr, dc, int(env.agent_orient[agent_id]))

        return 7
